from pathlib import Path
import hashlib,json
B=Path(__file__).resolve().parent
excluded_dirs={'__pycache__','reverse_input_root'}
include=[];excluded=[]
for p in sorted(B.rglob('*')):
 if not p.is_file() or p.name=='CURATION_MANIFEST.json':continue
 rel=p.relative_to(B);parts=rel.parts
 reason=None
 if p.is_symlink() or any(x in excluded_dirs for x in parts):reason='Transient import/cache or links to separately supplied original inputs; recreate via portable entrypoint.'
 elif 'portable_input' in parts:reason='Copied original reconstruction inputs; supply hash-verified restored archive and run forward stage.'
 elif parts[0] in ['corner_history','corner_h20'] and p.name.endswith('.csv.gz'):reason='Derived endpoint pair cache; recreate with extract_corner_history.py / extract_corner_h20.py. Retain per-pool hash receipts.'
 elif p.name=='native_history_events_rebuilt.csv.gz':reason='Derived supplemental original-metric cache; recreate with extract_corner_h20.py from compact original history requests and frozen fusion.'
 elif p.suffix=='.log':reason='Transient console logs; final receipts, candidate/failure ledgers and reports retained.'
 if reason:excluded.append({'path':str(rel),'bytes':p.stat().st_size,'reason':reason})
 else:include.append({'path':str(rel),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
(B/'CURATION_MANIFEST.json').write_text(json.dumps({'schema':'essential_learning_delivery_v1','relative_root':'audit_learning','include_files':include,'include_bytes':sum(x['bytes'] for x in include),'reproducible_exclusions':excluded,'external_prerequisites':['Original Pro bundle unpacked including analysis and interchangeability_20261020','Hash-verified restored A archive','Sibling audit_corner Python sources and metric receipts','Native endpoint caches regenerated by original frozen analysis/composition/fusion_runner.py using retained requests'],'important':'No unfavorable labels/results/candidate failures are excluded. Derived bulky caches can be regenerated; all frozen requests, registrations, full/fold memberships, paired common-support results and failure/optimizer ledgers are retained.'},indent=2))
print(len(include),sum(x['bytes'] for x in include))
